CREATE TABLE "Quotation" ("id" UUID NOT NULL,"number" TEXT NOT NULL,"customerId" UUID NOT NULL,"salesOrderId" UUID,"quotationDate" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"validUntil" TIMESTAMP(3) NOT NULL,"status" TEXT NOT NULL DEFAULT 'DRAFT',"subtotal" DECIMAL(18,2) NOT NULL,"tax" DECIMAL(18,2) NOT NULL DEFAULT 0,"total" DECIMAL(18,2) NOT NULL,"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Quotation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "QuotationItem" ("id" UUID NOT NULL,"quotationId" UUID NOT NULL,"productId" UUID NOT NULL,"descriptionSnapshot" TEXT NOT NULL,"quantity" DECIMAL(18,3) NOT NULL,"unitPrice" DECIMAL(18,2) NOT NULL,CONSTRAINT "QuotationItem_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Invoice" ("id" UUID NOT NULL,"number" TEXT NOT NULL,"customerId" UUID NOT NULL,"salesOrderId" UUID,"issueDate" TIMESTAMP(3) NOT NULL,"dueDate" TIMESTAMP(3) NOT NULL,"status" TEXT NOT NULL DEFAULT 'DRAFT',"subtotal" DECIMAL(18,2) NOT NULL,"tax" DECIMAL(18,2) NOT NULL DEFAULT 0,"total" DECIMAL(18,2) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Invoice_pkey" PRIMARY KEY ("id"));
CREATE TABLE "InvoiceItem" ("id" UUID NOT NULL,"invoiceId" UUID NOT NULL,"productId" UUID,"description" TEXT NOT NULL,"quantity" DECIMAL(18,3) NOT NULL,"unitPrice" DECIMAL(18,2) NOT NULL,CONSTRAINT "InvoiceItem_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Payment" ("id" UUID NOT NULL,"number" TEXT NOT NULL,"invoiceId" UUID NOT NULL,"paymentDate" TIMESTAMP(3) NOT NULL,"amount" DECIMAL(18,2) NOT NULL,"method" TEXT NOT NULL,"reference" TEXT,"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Payment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Supplier" ("id" UUID NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"category" TEXT NOT NULL,"materials" TEXT[] DEFAULT ARRAY[]::TEXT[],"pic" TEXT NOT NULL,"phone" TEXT NOT NULL,"email" TEXT,"address" TEXT NOT NULL,"taxInformation" TEXT,"paymentTerms" INTEGER NOT NULL DEFAULT 30,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"purchaseMonthToDate" DECIMAL(18,2) NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Supplier_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Quotation_number_key" ON "Quotation"("number"); CREATE INDEX "Quotation_customerId_status_idx" ON "Quotation"("customerId","status");
CREATE UNIQUE INDEX "Invoice_number_key" ON "Invoice"("number"); CREATE INDEX "Invoice_customerId_status_dueDate_idx" ON "Invoice"("customerId","status","dueDate");
CREATE UNIQUE INDEX "Payment_number_key" ON "Payment"("number"); CREATE INDEX "Payment_invoiceId_paymentDate_idx" ON "Payment"("invoiceId","paymentDate");
CREATE UNIQUE INDEX "Supplier_code_key" ON "Supplier"("code"); CREATE INDEX "Supplier_category_status_idx" ON "Supplier"("category","status");
ALTER TABLE "Quotation" ADD CONSTRAINT "Quotation_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "Customer"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Quotation" ADD CONSTRAINT "Quotation_salesOrderId_fkey" FOREIGN KEY ("salesOrderId") REFERENCES "SalesOrder"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "QuotationItem" ADD CONSTRAINT "QuotationItem_quotationId_fkey" FOREIGN KEY ("quotationId") REFERENCES "Quotation"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "QuotationItem" ADD CONSTRAINT "QuotationItem_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Invoice" ADD CONSTRAINT "Invoice_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "Customer"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Invoice" ADD CONSTRAINT "Invoice_salesOrderId_fkey" FOREIGN KEY ("salesOrderId") REFERENCES "SalesOrder"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "InvoiceItem" ADD CONSTRAINT "InvoiceItem_invoiceId_fkey" FOREIGN KEY ("invoiceId") REFERENCES "Invoice"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "InvoiceItem" ADD CONSTRAINT "InvoiceItem_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "Payment" ADD CONSTRAINT "Payment_invoiceId_fkey" FOREIGN KEY ("invoiceId") REFERENCES "Invoice"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
